from pathlib import Path
import json,statistics,hashlib
r=Path('/home/claude/code/EKA2L1');s=Path('/home/claude/.scratch/eka-benchmark');d=r/'src/tests/benchmark';p=d/'CONDITIONAL_RUNNER_LIMITS_EVIDENCE.json';e=json.loads(p.read_text());e['timing']={}
text='\n## Serial runner-limit timing\n\nAll 32 observations are retained. Values are mean elapsed seconds for identical guest work within each route; lower is faster. Each batch mirrors its first half, with a two-position rotation in batch B. The untouched live archive is separate from the matching binary control.\n\n| Route/batch | 512 regions matching | 64 regions | Uncapped | Live archive |\n| --- | ---: | ---: | ---: | ---: |\n'
results=[]
for scene in ['long','standard']:
 for batch in ['a','b']:
  path=s/f'conditional-runner-timing-{scene}-{batch}';rows=json.loads((path/'measurements.json').read_text());host=json.loads((s/f'conditional-runner-timing-{scene}-{batch}-host.json').read_text());assert len(rows)==8 and host['returncode']==0 and not host['foreign_jobs']
  expected=(6445351805,9476989025,380)if scene=='long'else(8980877653,11957513019,381)
  assert {tuple(x['measurement'][k] for k in ['first_instructions','last_instructions','presentations'])for x in rows}=={expected}
  reports={x['name']:json.loads((path/x['name']/'report.json').read_text())for x in rows}
  for name,q in reports.items():
   mode=name.rsplit('-',1)[0];assert q['execution_limits']==e['limits'][mode] and q['ir_mode']==7 and q['leaf_features']==0 and q['predicated_leaves']==1
   assert not q['exit_census'] and q['verify_aot']==0 and q['guest_profile_stride']==0 and not q['measurement']['detailed']
   assert q['tlb_hash']==1 and q['code_compare']==2 and q['code_lookup']==0 and q['eager_regions']==0 and q['shared_audio']
   assert q['wasm_sha256']==(json.loads((s/'predicated-leaf-candidate/source.json').read_text())['files']['eka2l1.wasm']if mode=='baseline'else e['archive']['files']['eka2l1.wasm'])
  modes=['control512','cap64','uncapped','baseline'];means={n:statistics.mean(x['measurement']['wall_seconds']for x in rows if x['name'].startswith(n+'-'))for n in modes}
  changes={n:{c:[next(x['measurement']['wall_seconds']for x in rows if x['name']==f'{c}-{rep}')/next(x['measurement']['wall_seconds']for x in rows if x['name']==f'{n}-{rep}')-1 for rep in [1,2]]for c in ['control512','baseline']}for n in ['cap64','uncapped']}
  e['timing'][scene+'-'+batch]=dict(rows=rows,reports=reports,host_observer=host,means=means,paired_throughput_changes=changes)
  text+='| '+scene+' '+batch+' | '+' | '.join(f'{means[n]:.4f}'for n in modes)+' |\n';results.append((scene,batch,means,changes))
for scene,batch,m,c in results:
 for n in ['cap64','uncapped']:text+=f"\n- {scene} {batch}, {n}: "+'; '.join(f"vs {ref}: {100*(m[ref]/m[n]-1):+.2f}% throughput; half-pairs {100*c[n][ref][0]:+.2f}% / {100*c[n][ref][1]:+.2f}%"for ref in ['control512','baseline'])+'.'
text+='\n\nPairs associate corresponding halves and are not all adjacent. Host observers detect watched competing jobs, not all host activity. Startup includes guest work and is not isolated compilation time. These timings do not establish an optimum outside the tested range. Diagnostic cost counters and any normal/live/audio delivery checks remain separate.\n'
e['status']='All 32 runner-limit observations retained; interpretation and counters pending; no deployment.'
e['harness'].update({n:dict(sha256=hashlib.sha256((s/n).read_bytes()).hexdigest(),source=(s/n).read_text())for n in ['record_conditional_runner_acceptance.py','record_conditional_runner_timings.py']})
p.write_text(json.dumps(e,indent=2)+'\n');p=d/'CONDITIONAL_RUNNER_LIMITS_RESULTS.md';p.write_text(p.read_text().split('\n## Serial runner-limit timing')[0]+text);print(text)
